// Index lookup for the 5 Joeys: roo-1 to roo-5
export const ROO_COLORWAYS = ['peach', 'blue', 'yellow', 'mint', 'lavender'] as const;
export type RooColorway = typeof ROO_COLORWAYS[number];

export function getJoeyStripFrame(colorway: RooColorway | string, frameIndex: number): string {
  const list = JOEY_STRIP_FRAMES[colorway] ?? JOEY_STRIP_FRAMES.peach;
  return list[Math.max(0, Math.min(list.length - 1, frameIndex))];
}
